function getTalentDomainInfo(talentName) {
  if (!talentName) return null;
  const clean = String(talentName).trim();
  return TALENT_DOMAINS.find(d => d.name === clean || d.code === clean || d.arCode === clean || `${d.code} ${d.name}` === clean || `${d.arCode} ${d.name}` === clean) || null;
}

// Student Avatar SVG Generator (Gender & Name Aware)
function createDefaultStudentPhoto(name, gender, idx = 1) {
  const isFemale = gender === 'انثى' || gender === 'أنثى';
  const palettes = isFemale
    ? [
        ['#0d9488', '#115e59', '#f0fdfa'],
        ['#7c3aed', '#5b21b6', '#f5f3ff'],
        ['#db2777', '#9d174d', '#fdf2f8'],
        ['#2563eb', '#1e40af', '#eff6ff']
      ]
    : [
        ['#0284c7', '#0c4a6e', '#f0f9ff'],
        ['#059669', '#065f46', '#ecfdf5'],
        ['#4f46e5', '#312e81', '#eef2ff'],
        ['#0f766e', '#134e4a', '#f0fdfa']
      ];
  const [bg1, bg2, accent] = palettes[idx % palettes.length];
  const initial = (name || 'ط').trim().charAt(0);
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 120" width="120" height="120">
    <defs>
      <linearGradient id="g${idx}" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stop-color="${bg1}"/>
        <stop offset="100%" stop-color="${bg2}"/>
      </linearGradient>
    </defs>
    <rect width="120" height="120" rx="24" fill="url(#g${idx})"/>
    <circle cx="60" cy="44" r="21" fill="${accent}" fill-opacity="0.92"/>
    ${isFemale
      ? `<path d="M36 44 C36 24, 84 24, 84 44 C84 52, 82 58, 78 61 C76 46, 44 46, 42 61 C38 58, 36 52, 36 44 Z" fill="${bg2}" fill-opacity="0.35"/>`
      : `<path d="M42 34 L60 24 L78 34 L60 42 Z" fill="#fbbf24"/>`
    }
    <path d="M24 106 C24 80, 96 80, 96 106 Z" fill="${accent}" fill-opacity="0.92"/>
    <circle cx="96" cy="24" r="14" fill="#ffffff" fill-opacity="0.22"/>
    <text x="96" y="29" text-anchor="middle" font-family="Cairo, sans-serif" font-size="14" font-weight="800" fill="#ffffff">${initial}</text>
  </svg>`;
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

