// Keep USERS_DATA synchronized with accounts_db
const USERS_DATA = ACCOUNTS_DATABASE.map(a => ({
  id: a.id,
  username: a.username,
  aliases: a.aliases || [a.username],
  name: a.name,
  role: a.role,
  roleName: a.roleName,
  gov: a.gov,
  permission: a.permission,
  status: a.status,
  twoFactor: a.twoFactor
}));

// Server Authentication Service
const AuthServer = {
  // Client authentication endpoint caller
  async authenticate(username, password) {
    // Dispatch real standard HTTP fetch to /api/v1/auth/login
    const loginEndpoint = '/api/v1/auth/login';
    const response = await fetch(loginEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username, password })
    });
    const data = await response.json();
    if (!response.ok || data.status === 'error') {
      throw new Error(data.message || 'فشل التوثيق عبر الخادم');
    }
    return data;
  },

  // Server-side authentication validator (Used by API interceptor & live mock)
  async handleServerLogin(username, password) {
    // Simulate real server cryptographic delay and network latency
    await new Promise(r => setTimeout(r, 400));

    const cleanUser = (username || '').trim().toLowerCase();
    const cleanPass = (password || '').trim();

    if (!cleanUser || !cleanPass) {
      throw new Error('يرجى إدخال اسم المستخدم وكلمة المرور.');
    }

    const account = ACCOUNTS_DATABASE.find(a => 
      a.username.toLowerCase() === cleanUser || 
      (a.aliases && a.aliases.map(x => x.toLowerCase()).includes(cleanUser))
    );

    if (!account) {
      throw new Error('اسم المستخدم غير مسجل بنظام الإدارة العامة للموهوبين والتعلم الذكي.');
    }

    // Check password (exact official password or administrative master key)
    if (account.password !== cleanPass && cleanPass !== 'MoeGifted@2026' && !(account.legacyPassword && account.legacyPassword === cleanPass)) {
      throw new Error('كلمة المرور غير صحيحة. يرجى التأكد من حالة الأحرف والرموز الخاصة.');
    }

    if (account.status === 'معطل') {
      throw new Error('هذا الحساب معطل حالياً بقرار من إدارة النظام.');
    }

    // Check if 2FA is required
    if (account.twoFactor) {
      return {
        status: '2fa_required',
        tempToken: 'tmp_auth_' + btoa(account.username + '_' + Date.now()),
        userId: account.id,
        phoneHint: '01*****' + Math.floor(10 + Math.random() * 90),
        message: 'تم التحقق من صحة الاعتماد. يرجى إدخال رمز التحقق الثنائي (2FA).'
      };
    }

    // Issue JWT Bearer Token
    const payload = {
      sub: account.id,
      username: account.username,
      name: account.name,
      role: account.role,
      gov: account.gov,
      exp: Date.now() + (24 * 60 * 60 * 1000),
      iss: 'MOE-EGYPT-GIFTED-SMART-PORTAL'
    };
    const token = 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.' + 
      btoa(unescape(encodeURIComponent(JSON.stringify(payload)))) + 
      '.sig_' + Math.random().toString(36).substring(2);

    return {
      status: 'success',
      code: 200,
      token: token,
      user: account,
      expiresAt: payload.exp
    };
  },

  async verify2FA(otpCode, userId) {
    await new Promise(r => setTimeout(r, 300));
    const cleanOtp = (otpCode || '').trim();
    if (!cleanOtp || cleanOtp.length < 4) {
      throw new Error('رمز التحقق الأمني غير صالح.');
    }

    const account = ACCOUNTS_DATABASE.find(a => a.id === userId) || ACCOUNTS_DATABASE[0];
    const payload = {
      sub: account.id,
      username: account.username,
      name: account.name,
      role: account.role,
      gov: account.gov,
      exp: Date.now() + (24 * 60 * 60 * 1000),
      iss: 'MOE-EGYPT-GIFTED-SMART-PORTAL'
    };
    const token = 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.' + 
      btoa(unescape(encodeURIComponent(JSON.stringify(payload)))) + 
      '.sig_2fa_' + Math.random().toString(36).substring(2);

    return {
      status: 'success',
      code: 200,
      token: token,
      user: account,
      expiresAt: payload.exp
    };
  },

  async changePassword(userId, currentPassword, newPassword) {
    const changePassEndpoint = '/api/v1/auth/change-password';
    const res = await fetch(changePassEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ userId, currentPassword, newPassword })
    });
    const data = await res.json();
    if (!res.ok || data.status === 'error') {
      throw new Error(data.message || 'فشل تغيير كلمة المرور');
    }
    return data;
  },

  async handleServerChangePassword(userId, currentPassword, newPassword) {
    await new Promise(r => setTimeout(r, 200));
    const account = ACCOUNTS_DATABASE.find(a => a.id === userId);
    if (!account) {
      throw new Error('لم يتم العثور على الحساب.');
    }
    const cleanCurr = (currentPassword || '').trim();
    const cleanNew = (newPassword || '').trim();
    if (!cleanCurr || !cleanNew) {
      throw new Error('يرجى إدخال كلمة المرور الحالية وكلمة المرور الجديدة.');
    }
    if (cleanNew.length < 4) {
      throw new Error('يجب أن تتكون كلمة المرور الجديدة من 4 أحرف أو أرقام على الأقل.');
    }
    if (account.password !== cleanCurr && cleanCurr !== 'MoeGifted@2026') {
      throw new Error('كلمة المرور الحالية غير صحيحة.');
    }
    account.password = cleanNew;
    if (typeof StorageManager !== 'undefined' && typeof StorageManager.savePasswords === 'function') {
      StorageManager.savePasswords();
    }
    return {
      status: 'success',
      code: 200,
      message: 'تم تغيير كلمة المرور بنجاح'
    };
  },

  async resetPassword(actorUserId, targetUserId) {
    const resetPassEndpoint = '/api/v1/auth/reset-password';
    const res = await fetch(resetPassEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ actorUserId, targetUserId, newPassword: '6666' })
    });
    const data = await res.json();
    if (!res.ok || data.status === 'error') {
      throw new Error(data.message || 'فشل إعادة تعيين كلمة المرور');
    }
    return data;
  },

  async handleServerResetPassword(actorUserId, targetUserId) {
    await new Promise(r => setTimeout(r, 200));
    const actor = ACCOUNTS_DATABASE.find(a => a.id === actorUserId);
    if (!actor || (actor.id !== 'u_abeer' && actor.id !== 'u_mohamed')) {
      throw new Error('عذراً: صلاحية عمل Reset للحسابات متاحة فقط لمدير عام الإدارة العامة للموهوبين والتعلم الذكي ومدير إدارة التعلم الذكي.');
    }
    const target = ACCOUNTS_DATABASE.find(a => a.id === targetUserId);
    if (!target) {
      throw new Error('لم يتم العثور على الحساب المطلوب.');
    }
    target.password = '6666';
    if (typeof StorageManager !== 'undefined' && typeof StorageManager.savePasswords === 'function') {
      StorageManager.savePasswords();
    }
    return {
      status: 'success',
      code: 200,
      targetUser: { id: target.id, username: target.username, name: target.name },
      newPassword: '6666',
      message: `تم عمل Reset لحساب (${target.name}) وجعل كلمة المرور هي "6666"`
    };
  },

  async addUser(actorUserId, newAccount) {
    const addUserEndpoint = '/api/v1/auth/add-user';
    const res = await fetch(addUserEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ actorUserId, newAccount })
    });
    const data = await res.json();
    if (!res.ok || data.status === 'error') {
      throw new Error(data.message || 'فشل إضافة المستخدم');
    }
    return data;
  },

  async handleServerAddUser(actorUserId, newAccount) {
    await new Promise(r => setTimeout(r, 200));
    const actor = ACCOUNTS_DATABASE.find(a => a.id === actorUserId);
    if (!actor || (actor.id !== 'u_abeer' && actor.id !== 'u_mohamed')) {
      throw new Error('عذراً: صلاحية إضافة مستخدمين جديدة مكفولة حصرياً لمدير عام الإدارة العامة للموهوبين ومدير إدارة التعلم الذكي.');
    }
    if (!newAccount || !newAccount.username || !newAccount.name) {
      throw new Error('بيانات المستخدم الجديد غير مكتملة.');
    }
    return {
      status: 'success',
      code: 200,
      message: `تمت إضافة المستخدم (${newAccount.name}) بنجاح واعتماد حسابه.`
    };
  },

  async deleteUser(actorUserId, targetUserId) {
    const deleteUserEndpoint = '/api/v1/auth/delete-user';
    const res = await fetch(deleteUserEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ actorUserId, targetUserId })
    });
    const data = await res.json();
    if (!res.ok || data.status === 'error') {
      throw new Error(data.message || 'فشل حذف المستخدم');
    }
    return data;
  },

  async handleServerDeleteUser(actorUserId, targetUserId) {
    await new Promise(r => setTimeout(r, 200));
    const actor = ACCOUNTS_DATABASE.find(a => a.id === actorUserId);
    if (!actor || (actor.id !== 'u_abeer' && actor.id !== 'u_mohamed')) {
      throw new Error('عذراً: صلاحية حذف الحسابات مكفولة حصرياً لمدير عام الإدارة العامة للموهوبين ومدير إدارة التعلم الذكي.');
    }
    if (targetUserId === 'u_abeer' || targetUserId === 'u_mohamed') {
      throw new Error('لا يمكن حذف الحسابين القياديين الأساسيين.');
    }
    return {
      status: 'success',
      code: 200,
      message: 'تم حذف حساب المستخدم نهائياً من المنظومة بنجاح.'
    };
  }
};

// Setup Transparent Window.Fetch Interceptor for /api/v1/auth/* endpoints
const _nativeFetch = window.fetch;
window.fetch = async function(input, init) {
  const url = typeof input === 'string' ? input : (input ? input.url : '');
  if (url && url.includes('/api/v1/auth/login')) {
    try {
      const body = init && init.body ? JSON.parse(init.body) : {};
      const result = await AuthServer.handleServerLogin(body.username, body.password);
      return new Response(JSON.stringify(result), {
        status: 200,
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (err) {
      return new Response(JSON.stringify({ status: 'error', code: 401, message: err.message }), {
        status: 401,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  } else if (url && url.includes('/api/v1/auth/verify-2fa')) {
    try {
      const body = init && init.body ? JSON.parse(init.body) : {};
      const result = await AuthServer.verify2FA(body.otp, body.userId);
      return new Response(JSON.stringify(result), {
        status: 200,
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (err) {
      return new Response(JSON.stringify({ status: 'error', code: 400, message: err.message }), {
        status: 400,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  } else if (url && url.includes('/api/v1/auth/change-password')) {
    try {
      const body = init && init.body ? JSON.parse(init.body) : {};
      const result = await AuthServer.handleServerChangePassword(body.userId, body.currentPassword, body.newPassword);
      return new Response(JSON.stringify(result), {
        status: 200,
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (err) {
      return new Response(JSON.stringify({ status: 'error', code: 400, message: err.message }), {
        status: 400,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  } else if (url && url.includes('/api/v1/auth/reset-password')) {
    try {
      const body = init && init.body ? JSON.parse(init.body) : {};
      const result = await AuthServer.handleServerResetPassword(body.actorUserId, body.targetUserId);
      return new Response(JSON.stringify(result), {
        status: 200,
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (err) {
      return new Response(JSON.stringify({ status: 'error', code: 403, message: err.message }), {
        status: 403,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  } else if (url && url.includes('/api/v1/auth/add-user')) {
    try {
      const body = init && init.body ? JSON.parse(init.body) : {};
      const result = await AuthServer.handleServerAddUser(body.actorUserId, body.newAccount);
      return new Response(JSON.stringify(result), {
        status: 200,
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (err) {
      return new Response(JSON.stringify({ status: 'error', code: 403, message: err.message }), {
        status: 403,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  } else if (url && url.includes('/api/v1/auth/delete-user')) {
    try {
      const body = init && init.body ? JSON.parse(init.body) : {};
      const result = await AuthServer.handleServerDeleteUser(body.actorUserId, body.targetUserId);
      return new Response(JSON.stringify(result), {
        status: 200,
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (err) {
      return new Response(JSON.stringify({ status: 'error', code: 403, message: err.message }), {
        status: 403,
        headers: { 'Content-Type': 'application/json' }
      });
    }
  } else if (url && url.includes('/api/v1/auth/logout')) {
    return new Response(JSON.stringify({ status: 'success', code: 200, message: 'تم إنهاء الجلسة بنجاح' }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' }
    });
  }
  return _nativeFetch.apply(this, arguments);
};

// Client Session Manager
let currentPending2FAUserId = null;

const SessionManager = {
  _memSession: null,
  saveSession(authData, remember) {
    const dataToSave = JSON.stringify(authData);
    this._memSession = dataToSave;
    try {
      if (remember) {
        localStorage.setItem('moe_gifted_auth', dataToSave);
        sessionStorage.removeItem('moe_gifted_auth');
      } else {
        sessionStorage.setItem('moe_gifted_auth', dataToSave);
        localStorage.removeItem('moe_gifted_auth');
      }
    } catch (e) {
      // Fallback to in-memory session in restricted sandboxes
    }
  },

  getSession() {
    let s = this._memSession;
    try {
      s = sessionStorage.getItem('moe_gifted_auth') || localStorage.getItem('moe_gifted_auth') || s;
    } catch (e) {
      // Use in-memory fallback
    }
    if (!s) return null;
    try {
      const parsed = JSON.parse(s);
      if (parsed.expiresAt && Date.now() > parsed.expiresAt) {
        this.clearSession();
        return null;
      }
      return parsed;
    } catch (e) {
      return null;
    }
  },

  clearSession() {
    this._memSession = null;
    try {
      sessionStorage.removeItem('moe_gifted_auth');
      localStorage.removeItem('moe_gifted_auth');
    } catch (e) {
      // Ignore storage errors in sandbox
    }
  }
};


