    if ((m = trimmed.match(/^(.+?)\s*\((\d+)\s*مراكز\)$/))) return `${tr(m[1])} (${m[2]} Centers)`;
    if ((m = trimmed.match(/^مديرية\s+(.+?)\s*\(نطاقك الحصري\)$/))) return `${tr(m[1])} Directorate (Your Assigned Scope)`;
    if ((m = trimmed.match(/^مديرية\s+(.+)$/))) return `${tr(m[1])} Directorate`;
    if ((m = trimmed.match(/^المعروض:\s*(\d+)$/))) return `Showing: ${m[1]}`;
    if ((m = trimmed.match(/^جاهزية\s*(\d+)%$/))) return `Readiness ${m[1]}%`;
