    if ((m = trimmed.match(/^تم التوثيق عبر الخادم بنجاح\s*-\s*الجلسة:\s*(.+)$/))) return `Authenticated via server - Session: ${m[1]}`;
    if ((m = trimmed.match(/^تحديث البيانات المدرسية والموهبة بمديرية\s+(.+)$/))) return `Updated school and talent record in ${tr(m[1])} Directorate`;
    if ((m = trimmed.match(/^تسجيل طالب جديد بمديرية\s+(.+?)\s*-\s*إدارة\s+(.+)$/))) return `Registered new student in ${tr(m[1])} Directorate - ${tr(m[2])} Admin`;
    if ((m = trimmed.match(/^تم تحديث بيانات الطالب\s+"(.+?)"\s*\(مديرية\s+(.+?)\)\s*بنجاح$/))) return `Student "${tr(m[1])}" (${tr(m[2])} Directorate) updated successfully`;
    if ((m = trimmed.match(/^تم تسجيل الطالب\s+"(.+?)"\s*بنجاح في مديرية\s+(.+)$/))) return `Student "${tr(m[1])}" registered successfully in ${tr(m[2])} Directorate`;
    if ((m = trimmed.match(/^تم حذف سجل الطالب\s+"(.+?)"\s*بنجاح$/))) return `Student record "${tr(m[1])}" deleted successfully`;
    if ((m = trimmed.match(/^تم إرسال سجل الطالب\s+"(.+?)"\s*للاعتماد إلى الإدارة العامة بالوزارة$/))) return `Student record "${tr(m[1])}" submitted to the General Administration for approval`;
    if ((m = trimmed.match(/^تم اعتماد سجل الطالب\s+"(.+?)"\s*وتوثيقه رسمياً$/))) return `Student record "${tr(m[1])}" officially approved and certified`;
