    if ((m = trimmed.match(/^تم حذف\s+"(.+?)"\s*\((.+?)\)\s*بنجاح$/))) return `Deleted "${tr(m[1])}" (${m[2]}) successfully`;
    if ((m = trimmed.match(/^تحديث بيانات المركز بمديرية\s+(.+?)\s*-\s*إدارة\s+(.+)$/))) return `Updated center details in ${tr(m[1])} Directorate - ${tr(m[2])} Admin`;
    if ((m = trimmed.match(/^إضافة مركز جديد بمديرية\s+(.+?)\s*-\s*إدارة\s+(.+)$/))) return `Added new center in ${tr(m[1])} Directorate - ${tr(m[2])} Admin`;
    if ((m = trimmed.match(/^حذف المركز من سجل مديرية\s+(.+?)\s*-\s*إدارة\s+(.+)$/))) return `Deleted center from ${tr(m[1])} Directorate - ${tr(m[2])} Admin`;
    if ((m = trimmed.match(/^تحديث نسبة الجاهزية إلى\s+(\d+)%$/))) return `Updated center readiness rate to ${m[1]}%`;
    if ((m = trimmed.match(/^تم حفظ تقرير فحص المركز وتحديث الجاهزية إلى\s+(\d+)%$/))) return `Saved center inspection report and updated readiness to ${m[1]}%`;
    if ((m = trimmed.match(/^تم تحديث الصورة الشخصية للطالب\s+"(.+?)"\s*بنجاح$/))) return `Updated personal photo for student "${tr(m[1])}" successfully`;
    if ((m = trimmed.match(/^تم إرفاق ومعاينة\s+(.+?)\s+للطالب بنجاح$/))) return `Attached and previewed ${tr(m[1])} for student successfully`;
    if ((m = trimmed.match(/^تحديث الصورة الشخصية للطالب بالملف التراكمي\s*\((.+?)\)$/))) return `Updated student photo in cumulative portfolio (${tr(m[1])})`;
    if ((m = trimmed.match(/^تم قراءة وفحص ملف Excel بنجاح\s*\((\d+)\s*طالب\)$/))) return `Excel file read and validated successfully (${m[1]} students)`;
    if ((m = trimmed.match(/^تم فحص ومعاينة الملف\s*\((\d+)\s*طالب\)$/))) return `File validated and previewed (${m[1]} students)`;

