    if ((m = trimmed.match(/^تلقائي\s*\(تم تجاهل\s*"(.+?)"\)$/))) return `Auto-filled (Ignored "${tr(m[1])}")`;
    if ((m = trimmed.match(/^اسم المحافظة\s*"(.+?)"\s*غير صحيح$/))) return `Governorate name "${tr(m[1])}" is invalid`;
    if ((m = trimmed.match(/^اسم الإدارة\s*"(.+?)"\s*خطأ\s*\(تم حذفه وتركه فارغاً للتعديل\)$/))) return `Administration "${tr(m[1])}" is invalid (cleared for editing)`;
    if ((m = trimmed.match(/^الرقم القومي\s*"(.+?)"\s*غير صحيح\s*\(يجب أن يتكون من 14 رقماً\)$/))) return `National ID "${m[1]}" is invalid (must be 14 digits)`;
    if ((m = trimmed.match(/^الرقم القومي\s*"(.+?)"\s*مكرر مع طالب مسجل مسبقاً$/))) return `National ID "${m[1]}" is duplicated with an existing student`;
    if ((m = trimmed.match(/^اسم الطالب\s*"(.+?)"\s*غير مكتمل\s*\(يلزم الاسم رباعياً بدون أرقام\)$/))) return `Student name "${tr(m[1])}" is incomplete (full 4-part name required without numbers)`;
    if ((m = trimmed.match(/^النوع\s*"(.+?)"\s*غير صحيح$/))) return `Gender "${tr(m[1])}" is invalid`;
    if ((m = trimmed.match(/^المرحلة الدراسية\s*"(.+?)"\s*غير صحيحة$/))) return `Educational stage "${tr(m[1])}" is invalid`;
    if ((m = trimmed.match(/^الصف الدراسي\s*"(.+?)"\s*غير صحيح$/))) return `Grade level "${tr(m[1])}" is invalid`;
    if ((m = trimmed.match(/^الصف\s*"(.+?)"\s*لا يتوافق مع مرحلة\s*"(.+?)"$/))) return `Grade "${tr(m[1])}" is incompatible with stage "${tr(m[2])}"`;
    if ((m = trimmed.match(/^رقم الهاتف\s*"(.+?)"\s*غير صحيح$/))) return `Phone number "${m[1]}" is invalid`;
    if ((m = trimmed.match(/^مجال الموهبة\s*"(.+?)"\s*غير مطابق للمجالات المعتمدة$/))) return `Talent domain "${tr(m[1])}" does not match approved domains`;
    if ((m = trimmed.match(/^الفئات\s*"(.+?)"\s*تحتوي على تصنيف غير صحيح$/))) return `Categories "${tr(m[1])}" contain an invalid classification`;
