// Print Gifted Centers Report
function printCentersReport() {
  if (state.currentView !== 'centers') {
    switchView('centers');
  }

  // Ensure renderCenters is called to have latest filtered list
  renderCenters();

  // Populate dynamic metadata into print centers header
  const filterGovEl = document.getElementById('center-filter-gov');
  const govText = (filterGovEl && filterGovEl.value) ? (filterGovEl.options[filterGovEl.selectedIndex]?.text || filterGovEl.value) : 'كافة المحافظات والمديريات التعليمية';

  const filterGov = filterGovEl ? filterGovEl.value : '';
  const searchEl = document.getElementById('center-filter-search');
  const searchQuery = (searchEl ? searchEl.value : '').toLowerCase().trim();

  let list = CENTERS_DATA;
  const allowedGov = getUserAllowedGov();
  if (allowedGov) {
    list = list.filter(c => isSameGov(c.gov, allowedGov));
  } else if (filterGov) {
    list = list.filter(c => isSameGov(c.gov, filterGov));
  }
  if (searchQuery) {
    list = list.filter(c =>
      (c.name || '').toLowerCase().includes(searchQuery) ||
      I18nManager.translateTextToEn(c.name || '').toLowerCase().includes(searchQuery) ||
      (c.school || '').toLowerCase().includes(searchQuery) ||
      I18nManager.translateTextToEn(c.school || '').toLowerCase().includes(searchQuery) ||
      (c.dept || '').toLowerCase().includes(searchQuery) ||
      I18nManager.translateTextToEn(c.dept || '').toLowerCase().includes(searchQuery) ||
      (c.gov || '').toLowerCase().includes(searchQuery) ||
      I18nManager.translateTextToEn(c.gov || '').toLowerCase().includes(searchQuery) ||
      (c.manager || '').toLowerCase().includes(searchQuery) ||
      I18nManager.translateTextToEn(c.manager || '').toLowerCase().includes(searchQuery) ||
      (c.id || '').toLowerCase().includes(searchQuery)
    );
  }

  const countText = `${list.length} مركزاً مسجلاً ومطابقاً للبحث`;

  const now = new Date();
  const dateStr = now.toLocaleDateString('ar-EG', { year: 'numeric', month: 'long', day: 'numeric' }) + ' - ' + now.toLocaleTimeString('ar-EG', { hour: '2-digit', minute: '2-digit' });

  const printGov = document.getElementById('print-centers-gov');
  const printCount = document.getElementById('print-centers-count');
  const printDate = document.getElementById('print-centers-date');

  if (printGov) printGov.textContent = govText;
  if (printCount) printCount.textContent = countText;
  if (printDate) printDate.textContent = dateStr;

  // Ensure all modals and login screen are hidden
  document.querySelectorAll('[id^="modal-"]').forEach(m => m.classList.add('hidden'));
  const loginScreen = document.getElementById('login-screen');
  if (loginScreen) loginScreen.classList.add('hidden');

  document.body.classList.add('printing-centers-mode');

  const cleanup = () => {
    document.body.classList.remove('printing-centers-mode');
  };

  window.addEventListener('afterprint', cleanup, { once: true });

  setTimeout(() => {
    window.print();
    setTimeout(cleanup, 2000);
  }, 100);
}


// Cumulative Portfolio Logic
function renderPortfolio() {
  const select = document.getElementById('portfolio-student-select');
  if (!select) return;

  const filtered = getFilteredStudents();
  select.innerHTML = '';
  filtered.forEach(s => {
    select.innerHTML += `<option value="${s.id}" ${s.id === state.selectedStudentId ? 'selected' : ''}>${s.name} (${s.gov})</option>`;
  });

  if (filtered.length > 0 && !filtered.find(s => s.id === state.selectedStudentId)) {
    state.selectedStudentId = filtered[0].id;
  }

  const student = STUDENTS_DATA.find(s => s.id === state.selectedStudentId) || filtered[0];
  if (!student) return;

  // Header info
  const photoUrl = getStudentPhotoUrl(student);
  document.getElementById('portfolio-name').textContent = student.name;
  const avatarContainer = document.getElementById('portfolio-avatar');
  if (avatarContainer) {
    avatarContainer.innerHTML = `<img src="${photoUrl}" alt="${student.name}" class="w-full h-full object-cover">`;
  }
  document.getElementById('portfolio-nid').textContent = student.nid;
  document.getElementById('portfolio-school').textContent = student.school;
  document.getElementById('portfolio-gov-dept').textContent = `${student.gov} - ${student.dept}`;
  document.getElementById('portfolio-grade').textContent = `${student.stage} - الصف ${student.grade}`;
  const portTInfo = getTalentDomainInfo(student.talent);
  const portGiftName = (portTInfo && portTInfo.defaultGift) || student.giftLevel || '';
  const portGInfo = getTalentDomainInfo(portGiftName);
  const portTLabel = (portTInfo && portTInfo.code) ? `${portTInfo.code} ${student.talent}` : student.talent;
  const portGLabel = (portGInfo && portGInfo.code) ? `${portGInfo.code} - ${portGiftName}` : portGiftName;
  document.getElementById('portfolio-talent').textContent = portGLabel ? `${portTLabel} (${portGLabel})` : portTLabel;
  const subjEl = document.getElementById('portfolio-academic-subjects');
  if (subjEl) {
    subjEl.textContent = student.academicSubjects && student.academicSubjects.trim() !== '' ? student.academicSubjects : 'غير محدد';
  }
  document.getElementById('portfolio-cat').textContent = (student.categories || []).join('، ');
  document.getElementById('portfolio-parent').textContent = `${student.parentName || 'ولي الأمر'} (${student.parentPhone || student.phone || 'بدون هاتف'})`;

  // Follow-up Card personal & academic excellence summary
  const followupPhoto = document.getElementById('followup-student-photo');
  if (followupPhoto) followupPhoto.src = photoUrl;
  const followupName = document.getElementById('followup-student-name');
  if (followupName) followupName.textContent = student.name;
  const followupSchool = document.getElementById('followup-student-school');
  if (followupSchool) followupSchool.textContent = `${student.school} (${student.gov} - ${student.dept})`;
  const followupSubj = document.getElementById('followup-academic-subjects');
  if (followupSubj) followupSubj.textContent = student.academicSubjects && student.academicSubjects.trim() !== '' ? student.academicSubjects : 'غير محدد';
  const followupTalent = document.getElementById('followup-student-talent');
  if (followupTalent) followupTalent.textContent = portGLabel ? `${portTLabel} — ${portGLabel}` : `${portTLabel} (${(student.categories || []).join('، ')})`;
  const followupPct = document.getElementById('followup-student-percentage');
  if (followupPct) followupPct.textContent = student.percentage ? `${student.percentage}%` : 'متميز';

  // Status badge
  const badge = document.getElementById('portfolio-badge-status');
  if (student.status === 'معتمد') {
    badge.className = 'bg-emerald-100 text-emerald-800 text-[11px] font-bold px-2.5 py-0.5 rounded-full';
    badge.innerHTML = '<i class="fa-solid fa-check ml-1"></i> معتمد رسمياً';
  } else if (student.status === 'مرسل للاعتماد') {
    badge.className = 'bg-amber-100 text-amber-800 text-[11px] font-bold px-2.5 py-0.5 rounded-full';
    badge.innerHTML = '<i class="fa-solid fa-clock ml-1"></i> بانتظار الاعتماد';
  } else {
    badge.className = 'bg-slate-100 text-slate-700 text-[11px] font-bold px-2.5 py-0.5 rounded-full';
    badge.textContent = student.status;
  }

  // Consent Tab sync
  document.getElementById('consent-student-name').textContent = student.name;
  document.getElementById('consent-student-stage').textContent = student.stage;
  document.getElementById('consent-school-name').textContent = student.school;
  document.getElementById('consent-dept-name').textContent = student.dept;
  document.getElementById('consent-parent-name').textContent = student.parentName || 'أحمد محمود';

  // Render current Rubric
  renderRubricTable();
}

function switchPortfolioTab(tabKey) {
  document.querySelectorAll('.portfolio-pane').forEach(el => el.classList.add('hidden'));
  const target = document.getElementById(tabKey);
  if (target) target.classList.remove('hidden');

  document.querySelectorAll('.portfolio-tab-btn').forEach(btn => {
    if (btn.dataset.tab === tabKey) {
      btn.classList.add('active', 'border-b-2', 'border-emerald-600', 'text-emerald-700');
      btn.classList.remove('text-slate-500');
    } else {
      btn.classList.remove('active', 'border-b-2', 'border-emerald-600', 'text-emerald-700');
      btn.classList.add('text-slate-500');
    }
  });
}

// Rubrics Table Renderer & Scorer
function renderRubricTable() {
  const tbody = document.getElementById('rubric-items-body');
  if (!tbody) return;

  const rubricKey = document.getElementById('rubric-type-select').value;
  state.selectedRubricKey = rubricKey;
  const rubric = RUBRICS_DATA[rubricKey];
  if (!rubric) return;

  tbody.innerHTML = '';
  rubric.items.forEach((itemText, idx) => {
    const tr = document.createElement('tr');
    tr.className = "hover:bg-slate-50 transition border-b";
    
    // Default checked radio: 4 or 3
    const defaultVal = (idx % 3 === 0) ? 4 : 3;

    tr.innerHTML = `
      <td class="py-2.5 px-3 text-center font-bold text-slate-400">${idx + 1}</td>
      <td class="py-2.5 px-3 font-medium text-slate-800 leading-relaxed">${itemText}</td>
      <td class="py-2.5 px-2 text-center">
        <input type="radio" name="rubric_item_${idx}" value="4" ${defaultVal === 4 ? 'checked' : ''} class="rubric-radio text-emerald-600 focus:ring-emerald-500">
      </td>
      <td class="py-2.5 px-2 text-center">
        <input type="radio" name="rubric_item_${idx}" value="3" ${defaultVal === 3 ? 'checked' : ''} class="rubric-radio text-blue-600 focus:ring-blue-500">
      </td>
      <td class="py-2.5 px-2 text-center">
        <input type="radio" name="rubric_item_${idx}" value="2" class="rubric-radio text-amber-600 focus:ring-amber-500">
      </td>
      <td class="py-2.5 px-2 text-center">
        <input type="radio" name="rubric_item_${idx}" value="1" class="rubric-radio text-rose-600 focus:ring-rose-500">
      </td>
    `;
    tbody.appendChild(tr);
  });

  calcRubricScore();
}

function calcRubricScore() {
  const radios = document.querySelectorAll('.rubric-radio:checked');
  let total = 0;
  radios.forEach(r => total += parseInt(r.value, 10));

  const count = document.querySelectorAll('#rubric-items-body tr').length;
  const maxScore = count * 4;
  const percentage = Math.round((total / maxScore) * 100);

  document.getElementById('rubric-total-score').textContent = total;
  document.getElementById('rubric-max-score').textContent = `/ ${maxScore}`;
  document.getElementById('rubric-percentage').textContent = `${percentage}%`;

  const verdictEl = document.getElementById('rubric-verdict');
  if (percentage >= 85) {
    verdictEl.className = 'bg-emerald-100 text-emerald-800 text-xs px-2.5 py-0.5 rounded font-black';
    verdictEl.textContent = 'موهبة استثنائية مؤكدة (فائقة)';
  } else if (percentage >= 70) {
    verdictEl.className = 'bg-blue-100 text-blue-800 text-xs px-2.5 py-0.5 rounded font-black';
    verdictEl.textContent = 'موهبة متقدمة تحتاج صقل ورعاية';
  } else if (percentage >= 50) {
    verdictEl.className = 'bg-amber-100 text-amber-800 text-xs px-2.5 py-0.5 rounded font-black';
    verdictEl.textContent = 'استعداد متوسط (موهبة كامنة)';
  } else {
    verdictEl.className = 'bg-rose-100 text-rose-800 text-xs px-2.5 py-0.5 rounded font-black';
    verdictEl.textContent = 'يحتاج برامج استكشافية إضافية';
  }
}

function saveRubric() {
  const total = document.getElementById('rubric-total-score').textContent;
  const pct = document.getElementById('rubric-percentage').textContent;
  const rubricKey = state.selectedRubricKey;
  const rubricTitle = RUBRICS_DATA[rubricKey].title;
  const student = STUDENTS_DATA.find(s => s.id === state.selectedStudentId);

  if (student) {
    if (!student.evaluations) student.evaluations = {};
    student.evaluations[rubricKey] = {
      title: rubricTitle,
      total: total,
      pct: pct,
      date: new Date().toISOString().replace('T', ' ').substring(0, 16)
    };
    if (typeof StorageManager !== 'undefined') StorageManager.saveStudents();
  }

  logAudit('تقييم موهبة', `الطالب: ${student ? student.name : 'غير محدد'}`, `اعتماد نتيجة ${rubricTitle} بمجموع ${total} (${pct})`);
  showToast(`تم حفظ واعتماد بطاقة تقييم "${rubricTitle}" بنتيجة ${pct} بنجاح`, 'success');
}


