// Gifted Centers Directory, CRUD (Add / Edit / Delete) & Inspection
function renderCenters() {
  const grid = document.getElementById('centers-grid');
  if (!grid) return;

  populateGovDropdowns();

  const filterGovEl = document.getElementById('center-filter-gov');
  const filterGov = filterGovEl ? filterGovEl.value : '';
  const searchEl = document.getElementById('center-filter-search');
  const searchQuery = (searchEl ? searchEl.value : '').toLowerCase().trim();

  let list = CENTERS_DATA;

  // Role based filtering
  const allowedGov = getUserAllowedGov();
  if (allowedGov) {
    list = list.filter(c => isSameGov(c.gov, allowedGov));
  } else if (filterGov) {
    list = list.filter(c => isSameGov(c.gov, filterGov));
  }

  if (searchQuery) {
    list = list.filter(c =>
      (c.name || '').toLowerCase().includes(searchQuery) ||
      (c.school || '').toLowerCase().includes(searchQuery) ||
      (c.dept || '').toLowerCase().includes(searchQuery) ||
      (c.gov || '').toLowerCase().includes(searchQuery) ||
      (c.manager || '').toLowerCase().includes(searchQuery) ||
      (c.id || '').toLowerCase().includes(searchQuery)
    );
  }

  const showingBadge = document.getElementById('centers-showing-badge');
  if (showingBadge) {
    showingBadge.textContent = `المعروض: ${list.length}`;
  }

  grid.innerHTML = '';

  // Populate printable centers table
  const tbody = document.getElementById('centers-table-body');
  if (tbody) {
    tbody.innerHTML = '';
    list.forEach((c, idx) => {
      const tr = document.createElement('tr');
      tr.className = idx % 2 === 0 ? "bg-white" : "bg-slate-50";
      tr.innerHTML = `
        <td class="py-2 px-2 text-center font-bold text-slate-500">${idx + 1}</td>
        <td class="py-2 px-2 font-bold text-slate-900">${c.gov || '-'}</td>
        <td class="py-2 px-2 text-slate-700">${c.dept || '-'}</td>
        <td class="py-2 px-2 font-bold text-brand-900">${c.name || '-'}</td>
        <td class="py-2 px-2 text-slate-700">${c.school || '-'}</td>
        <td class="py-2 px-2 text-slate-800">${c.manager || '-'}</td>
        <td class="py-2 px-2 text-center font-mono text-slate-700" dir="ltr">${c.phone || '-'}</td>
        <td class="py-2 px-2 text-center">
          <span class="bg-emerald-50 text-emerald-800 border border-emerald-300 text-[10px] font-bold px-2 py-0.5 rounded-full inline-block">${c.status || 'نشط ومفعل'}</span>
        </td>
      `;
      tbody.appendChild(tr);
    });
  }

  if (list.length === 0) {
    grid.innerHTML = '<p class="col-span-3 text-center py-8 text-slate-400 font-bold">لا توجد مراكز مطابقة لفلترة البحث</p>';
    return;
  }

  const isViewer = state.currentUser && state.currentUser.role === 'general_viewer';

  list.forEach(c => {
    const canManageCenter = !isViewer && (!allowedGov || isSameGov(c.gov, allowedGov));
    const card = document.createElement('div');
    card.className = "bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col justify-between hover:border-cyan-300 transition";
    card.innerHTML = `
      <div>
        <div class="flex items-center justify-between mb-2">
          <span class="text-[10px] font-bold bg-cyan-100 text-cyan-800 px-2 py-0.5 rounded">${c.id}</span>
          <span class="text-[10px] font-bold text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-full"><i class="fa-solid fa-circle-check ml-1"></i> جاهزية ${c.readiness}%</span>
        </div>
        <h5 class="font-bold text-slate-900 text-xs mb-1">${c.name}</h5>
        <p class="text-slate-500 text-[11px] mb-2"><i class="fa-solid fa-location-dot ml-1 text-slate-400"></i> ${c.gov} - ${c.dept}</p>
        <div class="text-[10px] text-slate-600 space-y-0.5 bg-slate-50 p-2 rounded-lg border">
          <p><b>المقر:</b> ${c.school}</p>
          <p><b>المسئول:</b> ${c.manager}</p>
          <p><b>الهاتف:</b> <span class="font-mono">${c.phone || 'غير محدد'}</span></p>
          <p><b>الحالة:</b> <span class="font-bold text-slate-800">${c.status}</span></p>
        </div>
      </div>
      <div class="mt-3 pt-2 border-t flex items-center gap-1.5">
        <button class="btn-inspect-center flex-1 py-1.5 px-2 bg-cyan-50 hover:bg-cyan-100 text-cyan-800 font-bold text-[11px] rounded-lg transition" data-id="${c.id}" title="فحص وتقييم تجهيزات المركز">
          <i class="fa-solid fa-clipboard-check ml-1"></i> فحص التجهيزات
        </button>
        ${canManageCenter ? `
          <button class="btn-edit-center py-1.5 px-2.5 bg-blue-50 hover:bg-blue-100 text-blue-700 font-bold text-[11px] rounded-lg transition" data-id="${c.id}" title="تعديل بيانات المركز">
            <i class="fa-solid fa-pen-to-square"></i> تعديل
          </button>
          <button class="btn-delete-center py-1.5 px-2.5 bg-rose-50 hover:bg-rose-100 text-rose-700 font-bold text-[11px] rounded-lg transition" data-id="${c.id}" title="حذف المركز">
            <i class="fa-solid fa-trash-can"></i> حذف
          </button>
        ` : ''}
      </div>
    `;
    grid.appendChild(card);
  });
}

function updateCenterFormReadinessPreview() {
  const cbs = document.querySelectorAll('.form-center-equip-cb');
  if (!cbs.length) return 100;
  let checked = 0;
  cbs.forEach(cb => { if (cb.checked) checked++; });
  const pct = Math.round((checked / cbs.length) * 100);
  const badge = document.getElementById('inp-center-readiness-preview');
  if (badge) {
    badge.textContent = `جاهزية ${pct}%`;
  }
  return pct;
}

function openCenterFormModal(centerId = null) {
  if (state.currentUser && state.currentUser.role === 'general_viewer') {
    showToast('عذراً: حسابك يمتلك صلاحية عرض فقط ولا يمكنه إضافة أو تعديل بيانات المراكز.', 'warning');
    return;
  }

  const modal = document.getElementById('modal-center-form');
  const form = document.getElementById('form-center');
  const titleEl = document.getElementById('modal-center-form-title');
  const idField = document.getElementById('center-form-id');
  const allowedGov = getUserAllowedGov();

  if (!modal || !form) return;
  form.reset();
  populateGovDropdowns();

  if (centerId) {
    const c = CENTERS_DATA.find(x => x.id === centerId);
    if (!c) return;

    if (allowedGov && !isSameGov(c.gov, allowedGov)) {
      showToast(`غير مسموح: لا يمكنك تعديل مركز يتبع محافظة أخرى (${c.gov}).`, 'error');
      return;
    }

    const effectiveGov = allowedGov || resolveGovKey(c.gov);
    if (titleEl) {
      titleEl.innerHTML = `<i class="fa-solid fa-pen-to-square text-cyan-600"></i> تعديل بيانات المركز (${c.id})`;
    }
    idField.value = c.id;
    document.getElementById('inp-center-name').value = c.name || '';
    const govSelect = document.getElementById('inp-center-gov');
    if (govSelect) govSelect.value = effectiveGov;
    const deptSelect = document.getElementById('inp-center-dept');
    updateDeptDropdown(effectiveGov, deptSelect);
    if (deptSelect) deptSelect.value = c.dept || '';

    document.getElementById('inp-center-school').value = c.school || '';
    document.getElementById('inp-center-manager').value = c.manager || '';
    document.getElementById('inp-center-phone').value = c.phone || '';
    document.getElementById('inp-center-status').value = c.status || 'مفعل ومجهز بالكامل';

    document.querySelectorAll('.form-center-equip-cb').forEach(cb => {
      const key = cb.dataset.key;
      cb.checked = c.equipment && typeof c.equipment[key] !== 'undefined' ? Boolean(c.equipment[key]) : true;
    });
  } else {
    if (titleEl) {
      titleEl.innerHTML = allowedGov
        ? `<i class="fa-solid fa-plus text-cyan-600"></i> إضافة مركز جديد (مديرية ${allowedGov})`
        : `<i class="fa-solid fa-plus text-cyan-600"></i> إضافة مركز رعاية موهوبين وتعلم ذكي جديد`;
    }
    idField.value = '';
    if (allowedGov) {
      const govSelect = document.getElementById('inp-center-gov');
      if (govSelect) {
        govSelect.value = allowedGov;
        updateDeptDropdown(allowedGov, document.getElementById('inp-center-dept'));
      }
    }
    document.querySelectorAll('.form-center-equip-cb').forEach(cb => {
      cb.checked = true;
    });
  }

  updateCenterFormReadinessPreview();
  modal.classList.remove('hidden');
}

function handleCenterFormSubmit(e) {
  e.preventDefault();
  if (state.currentUser && state.currentUser.role === 'general_viewer') {
    showToast('عذراً: حسابك يمتلك صلاحية عرض فقط ولا يمكنه حفظ التعديلات.', 'error');
    return;
  }

  const idVal = document.getElementById('center-form-id').value.trim();
  const name = document.getElementById('inp-center-name').value.trim();
  const selectedGov = document.getElementById('inp-center-gov').value;
  const dept = document.getElementById('inp-center-dept').value;
  const school = document.getElementById('inp-center-school').value.trim();
  const manager = document.getElementById('inp-center-manager').value.trim();
  const phone = document.getElementById('inp-center-phone').value.trim();
  const status = document.getElementById('inp-center-status').value;
  const allowedGov = getUserAllowedGov();

  if (allowedGov && selectedGov && !isSameGov(selectedGov, allowedGov)) {
    showToast(`غير مسموح: بصفتك مسئول مديرية ${allowedGov}، يُسمح لك بإدارة مراكز محافظتك (${allowedGov}) فقط.`, 'error');
    return;
  }

  const gov = allowedGov ? allowedGov : resolveGovKey(selectedGov);
  if (!gov || !GOV_DEPTS[gov]) {
    showToast('يرجى اختيار المحافظة / المديرية بشكل صحيح.', 'warning');
    return;
  }

  if (!dept) {
    showToast('يرجى اختيار الإدارة التعليمية التابع لها المركز.', 'warning');
    return;
  }

  const equipment = {};
  let checkedCount = 0;
  const cbs = document.querySelectorAll('.form-center-equip-cb');
  cbs.forEach(cb => {
    equipment[cb.dataset.key] = cb.checked;
    if (cb.checked) checkedCount++;
  });
  const readiness = cbs.length > 0 ? Math.round((checkedCount / cbs.length) * 100) : 95;

  if (idVal) {
    const idx = CENTERS_DATA.findIndex(c => c.id === idVal);
    if (idx === -1) return;
    if (allowedGov && !isSameGov(CENTERS_DATA[idx].gov, allowedGov)) {
      showToast(`غير مسموح: لا يمكنك تعديل مركز خارج مديرية ${allowedGov}.`, 'error');
      return;
    }
    CENTERS_DATA[idx] = {
      ...CENTERS_DATA[idx],
      name,
      gov,
      dept,
      school,
      manager,
      phone: phone || CENTERS_DATA[idx].phone,
      status,
      readiness,
      equipment
    };
    logAudit('تعديل بيانات مركز', `${idVal} (${name})`, `تحديث بيانات المركز بمديرية ${gov} - إدارة ${dept}`);
    showToast(`تم تحديث بيانات "${name}" بنجاح`, 'success');
  } else {
    const maxNum = CENTERS_DATA.reduce((acc, item) => {
      const m = String(item.id || '').match(/(\d+)$/);
      return m ? Math.max(acc, parseInt(m[1], 10)) : acc;
    }, CENTERS_DATA.length);
    const newId = `CTR-${String(maxNum + 1).padStart(3, '0')}`;
    const newCenter = {
      id: newId,
      name,
      gov,
      dept,
      school,
      phone: phone || `02-2794${String(maxNum + 1).padStart(4, '0')}`,
      manager,
      readiness,
      status,
      equipment
    };
    CENTERS_DATA.unshift(newCenter);
    logAudit('إضافة مركز جديد', `${newId} (${name})`, `إضافة مركز جديد بمديرية ${gov} - إدارة ${dept}`);
    showToast(`تمت إضافة المركز "${name}" (${newId}) بنجاح`, 'success');
  }

  if (typeof StorageManager !== 'undefined') StorageManager.saveCenters();
  document.getElementById('modal-center-form').classList.add('hidden');
  renderCenters();
  if (state.currentView === 'reports') renderReports();
}

function deleteCenter(centerId) {
  if (state.currentUser && state.currentUser.role === 'general_viewer') {
    showToast('عذراً: حسابك يمتلك صلاحية عرض فقط ولا يمكنه حذف المراكز.', 'warning');
    return;
  }
  const idx = CENTERS_DATA.findIndex(c => c.id === centerId);
  if (idx === -1) return;
  const c = CENTERS_DATA[idx];
  const allowedGov = getUserAllowedGov();
  if (allowedGov && !isSameGov(c.gov, allowedGov)) {
    showToast(`غير مسموح: لا يمكنك حذف مركز من خارج مديرية ${allowedGov}.`, 'error');
    return;
  }
  CENTERS_DATA.splice(idx, 1);
  if (typeof StorageManager !== 'undefined') StorageManager.saveCenters();
  logAudit('حذف مركز', `${c.id} (${c.name})`, `حذف المركز من سجل مديرية ${c.gov} - إدارة ${c.dept}`);
  showToast(`تم حذف "${c.name}" (${c.id}) بنجاح`, 'warning');
  renderCenters();
  if (state.currentView === 'reports') renderReports();
}

function openCenterModal(centerId) {
  const c = CENTERS_DATA.find(x => x.id === centerId);
  if (!c) return;
  state.activeCenterAudit = c;

  document.getElementById('center-modal-title').innerHTML = `<i class="fa-solid fa-building-circle-check text-cyan-600"></i> فحص تجهيزات: ${c.name}`;
  document.getElementById('center-modal-sub').textContent = `${c.school} (${c.gov} - إدارة ${c.dept})`;
  document.getElementById('center-modal-readiness').textContent = `${c.readiness}%`;

  const listContainer = document.getElementById('center-equipment-list');
  listContainer.innerHTML = '';

  const equipLabels = {
    room: "قاعة حكومية في وسط المدينة جيدة التهوية (ص 39)",
    whiteboard: "سبورة تفاعلية ذكية أو جهاز عرض داتا شو",
    computers: "أجهزة كمبيوتر حديثة ومتصلة",
    laptop: "جهاز لابتوب متنقل للأعمال",
    internet: "توصيل خدمة إنترنت فائق السرعة",
    printer: "طابعة ليزر متعددة الوظائف",
    copier: "ماكينة تصوير مستندات",
    robotics: "أجهزة روبوت لتنمية مهارات الفك والتركيب",
    furniture: "ترابيزات وكراسي ودواليب حفظ كافية"
  };

  for (const [key, label] of Object.entries(equipLabels)) {
    const isChecked = c.equipment ? c.equipment[key] : true;
    listContainer.innerHTML += `
      <label class="flex items-center space-x-2 rtl:space-x-reverse p-2 bg-white rounded-lg border hover:bg-slate-50 cursor-pointer">
        <input type="checkbox" class="center-equip-cb text-cyan-600 focus:ring-cyan-500 rounded" data-key="${key}" ${isChecked ? 'checked' : ''}>
        <span class="text-[11px] font-semibold text-slate-700">${label}</span>
      </label>
    `;
  }

  document.getElementById('modal-center').classList.remove('hidden');
}

function saveCenterAudit() {
  if (!state.activeCenterAudit) return;
  const checkboxes = document.querySelectorAll('.center-equip-cb');
  let checkedCount = 0;
  checkboxes.forEach(cb => {
    const key = cb.dataset.key;
    state.activeCenterAudit.equipment[key] = cb.checked;
    if (cb.checked) checkedCount++;
  });

  const readiness = Math.round((checkedCount / checkboxes.length) * 100);
  state.activeCenterAudit.readiness = readiness;
  state.activeCenterAudit.status = readiness >= 80 ? 'مفعل ومجهز بالكامل' : 'قيد استكمال التجهيزات';
  if (typeof StorageManager !== 'undefined') StorageManager.saveCenters();

  logAudit('فحص مركز', state.activeCenterAudit.name, `تحديث نسبة الجاهزية إلى ${readiness}%`);
  showToast(`تم حفظ تقرير فحص المركز وتحديث الجاهزية إلى ${readiness}%`, 'success');
  document.getElementById('modal-center').classList.add('hidden');
  renderCenters();
}


