function openCreativityQuiz() {
  const modal = document.getElementById('modal-quiz');
  const container = document.getElementById('quiz-questions-list');
  container.innerHTML = '';

  QUIZ_ITEMS.forEach((q, idx) => {
    container.innerHTML += `
      <div class="p-2.5 flex flex-col sm:flex-row sm:items-center justify-between gap-2 hover:bg-slate-50">
        <span class="text-[11px] text-slate-800 font-medium">${idx + 1}. ${q}</span>
        <div class="flex items-center gap-3 self-end sm:self-auto shrink-0">
          <label class="text-[10px] flex items-center gap-1 cursor-pointer"><input type="radio" name="q_${idx}" value="3" checked> نعم (3)</label>
          <label class="text-[10px] flex items-center gap-1 cursor-pointer"><input type="radio" name="q_${idx}" value="2"> أحياناً (2)</label>
          <label class="text-[10px] flex items-center gap-1 cursor-pointer"><input type="radio" name="q_${idx}" value="1"> لا (1)</label>
        </div>
      </div>
    `;
  });

  calcQuiz();
  modal.classList.remove('hidden');
}

function calcQuiz() {
  let score = 0;
  for (let i = 0; i < QUIZ_ITEMS.length; i++) {
    const checked = document.querySelector(`input[name="q_${i}"]:checked`);
    if (checked) score += parseInt(checked.value, 10);
  }
  document.getElementById('quiz-total-score').textContent = score;

  const badge = document.getElementById('quiz-result-badge');
  if (score >= 35) {
    badge.className = 'mr-2 text-xs font-bold px-2.5 py-0.5 rounded bg-emerald-100 text-emerald-800';
    badge.textContent = 'ممتاز: قدرات ابتكارية استثنائية';
  } else if (score >= 25) {
    badge.className = 'mr-2 text-xs font-bold px-2.5 py-0.5 rounded bg-blue-100 text-blue-800';
    badge.textContent = 'جيد: استعداد ابتكاري متقدم';
  } else {
    badge.className = 'mr-2 text-xs font-bold px-2.5 py-0.5 rounded bg-amber-100 text-amber-800';
    badge.textContent = 'يحتاج إلى تحفيز بيئي وتدريب';
  }
}

