// Reports View
function renderReports() {
  const tbody = document.getElementById('reports-gov-table-body');
  if (!tbody) return;

  tbody.innerHTML = '';
  let sumDepts = 0;
  let sumCenters = 0;
  let sumTotal = 0;
  let sumGifted = 0;
  let sumInnov = 0;
  let sumExcel = 0;
  let sumDis = 0;
  let sumApproved = 0;

  const govKeys = Object.keys(GOV_DEPTS);
  govKeys.forEach((gov, idx) => {
    const depts = GOV_DEPTS[gov] || [];
    const centersCount = CENTERS_DATA.filter(c => isSameGov(c.gov, gov)).length;
    const govStudents = STUDENTS_DATA.filter(s => isSameGov(s.gov, gov));
    const total = govStudents.length;
    const gifted = govStudents.filter(s => (s.categories || []).includes('موهوبين')).length;
    const innov = govStudents.filter(s => (s.categories || []).includes('مبتكرين')).length;
    const excel = govStudents.filter(s => (s.categories || []).includes('فائقين')).length;
    const dis = govStudents.filter(s => (s.categories || []).includes('ذوي الهمم') || (s.disability && s.disability !== '')).length;
    const approved = govStudents.filter(s => s.status === 'معتمد').length;
    const pct = total > 0 ? Math.round((approved / total) * 100) : 100;

    sumDepts += depts.length;
    sumCenters += centersCount;
    sumTotal += total;
    sumGifted += gifted;
    sumInnov += innov;
    sumExcel += excel;
    sumDis += dis;
    sumApproved += approved;

    tbody.innerHTML += `
      <tr class="hover:bg-slate-50 border-b">
        <td class="py-2.5 px-2 text-center font-bold text-slate-500">${idx + 1}</td>
        <td class="py-2.5 px-3 font-bold text-slate-900">${gov}</td>
        <td class="py-2.5 px-3 text-center text-slate-600">${depts.length}</td>
        <td class="py-2.5 px-3 text-center font-bold text-cyan-700">${centersCount}</td>
        <td class="py-2.5 px-3 text-center font-bold text-brand-700">${total}</td>
        <td class="py-2.5 px-3 text-center text-blue-600">${gifted}</td>
        <td class="py-2.5 px-3 text-center text-amber-600">${innov}</td>
        <td class="py-2.5 px-3 text-center text-emerald-600">${excel}</td>
        <td class="py-2.5 px-3 text-center text-purple-600">${dis}</td>
        <td class="py-2.5 px-3 text-center">
          <span class="bg-emerald-100 text-emerald-800 text-[10px] font-bold px-2 py-0.5 rounded-full">${pct}%</span>
        </td>
      </tr>
    `;
  });

  const overallPct = sumTotal > 0 ? Math.round((sumApproved / sumTotal) * 100) : 100;
  const tfoot = document.getElementById('reports-gov-table-foot');
  if (tfoot) {
    tfoot.innerHTML = `
      <tr class="bg-slate-100 font-black text-slate-900 border-t-2 border-slate-300">
        <td colspan="2" class="py-3 px-3 text-right font-black text-slate-900">الإجمالي العام للجمهورية (27 مديرية تعليمية)</td>
        <td class="py-3 px-3 text-center font-black text-slate-900">${sumDepts}</td>
        <td class="py-3 px-3 text-center font-black text-cyan-800">${sumCenters}</td>
        <td class="py-3 px-3 text-center font-black text-brand-800">${sumTotal}</td>
        <td class="py-3 px-3 text-center font-black text-blue-700">${sumGifted}</td>
        <td class="py-3 px-3 text-center font-black text-amber-700">${sumInnov}</td>
        <td class="py-3 px-3 text-center font-black text-emerald-700">${sumExcel}</td>
        <td class="py-3 px-3 text-center font-black text-purple-700">${sumDis}</td>
        <td class="py-3 px-3 text-center">
          <span class="bg-emerald-200 text-emerald-950 text-[10px] font-black px-2.5 py-0.5 rounded-full">${overallPct}%</span>
        </td>
      </tr>
    `;
  }

  // Update print header summary fields
  const isEn = typeof I18nManager !== 'undefined' && I18nManager.currentLang === 'en';
  const scopeEl = document.getElementById('print-comp-scope');
  const deptsEl = document.getElementById('print-comp-depts');
  const centersEl = document.getElementById('print-comp-centers');
  const studentsEl = document.getElementById('print-comp-students');
  const giftedInnovEl = document.getElementById('print-comp-gifted-innov');
  const excelDisEl = document.getElementById('print-comp-excel-dis');
  const approvalEl = document.getElementById('print-comp-approval');
  const dateEl = document.getElementById('print-comp-date');

  if (scopeEl) scopeEl.textContent = isEn ? `All Educational Directorates (${govKeys.length} Directorates)` : `جميع المديريات التعليمية (${govKeys.length} مديرية)`;
  if (deptsEl) deptsEl.textContent = isEn ? `${sumDepts} Administrations` : `${sumDepts} إدارة تعليمية`;
  if (centersEl) centersEl.textContent = isEn ? `${sumCenters} Certified Centers` : `${sumCenters} مركزاً معتمداً`;
  if (studentsEl) studentsEl.textContent = isEn ? `${sumTotal} Registered Students` : `${sumTotal} طالباً وطالبة`;
  if (giftedInnovEl) giftedInnovEl.textContent = isEn ? `Gifted: ${sumGifted} | Innovators: ${sumInnov}` : `موهوبين: ${sumGifted} | مبتكرين: ${sumInnov}`;
  if (excelDisEl) excelDisEl.textContent = isEn ? `High Achievers: ${sumExcel} | Special Needs: ${sumDis}` : `فائقين: ${sumExcel} | ذوي الهمم: ${sumDis}`;
  if (approvalEl) approvalEl.textContent = isEn ? `${overallPct}% (${sumApproved} Approved)` : `${overallPct}% (${sumApproved} معتمد)`;
  if (dateEl) {
    const now = new Date();
    dateEl.textContent = now.toLocaleDateString(isEn ? 'en-US' : 'ar-EG', { year: 'numeric', month: 'long', day: 'numeric' }) + ' - ' + now.toLocaleTimeString(isEn ? 'en-US' : 'ar-EG', { hour: '2-digit', minute: '2-digit' });
  }
}

