// Accessibility & UI Controls
function toggleContrast() {
  document.body.classList.toggle('high-contrast');
  const btn = document.getElementById('toggle-contrast');
  if (btn) {
    btn.textContent = document.body.classList.contains('high-contrast') ? 'إيقاف' : 'تشغيل';
  }
}

function setFontSize(dir) {
  const sizes = ['font-size-sm', 'font-size-base', 'font-size-lg', 'font-size-xl'];
  let currentIdx = 1;
  sizes.forEach((s, i) => {
    if (document.body.classList.contains(s)) currentIdx = i;
  });

  document.body.classList.remove(...sizes);
  if (dir === 0) {
    document.body.classList.add('font-size-base');
  } else if (dir > 0 && currentIdx < sizes.length - 1) {
    document.body.classList.add(sizes[currentIdx + 1]);
  } else if (dir < 0 && currentIdx > 0) {
    document.body.classList.add(sizes[currentIdx - 1]);
  } else {
    document.body.classList.add(sizes[currentIdx]);
  }
}

function toggleRuler() {
  const ruler = document.getElementById('reading-ruler');
  const btn = document.getElementById('toggle-ruler');
  if (!ruler || !btn) return;

  if (ruler.style.display === 'block') {
    ruler.style.display = 'none';
    btn.textContent = 'تفعيل';
    window.onmousemove = null;
  } else {
    ruler.style.display = 'block';
    btn.textContent = 'إلغاء';
    window.onmousemove = (e) => {
      ruler.style.top = `${e.clientY - 18}px`;
    };
  }
}

function toggleLanguage(e) {
  if (e && typeof e.preventDefault === 'function') e.preventDefault();
  if (state.currentLang === 'ar') {
    state.currentLang = 'en';
    document.documentElement.dir = 'ltr';
    document.documentElement.lang = 'en';
  } else {
    state.currentLang = 'ar';
    document.documentElement.dir = 'rtl';
    document.documentElement.lang = 'ar';
  }

  // Ensure observer is active and immediately translate or restore all DOM text nodes and attributes
  I18nManager.initObserver();
  I18nManager.applyLanguageToDOM(document.body);

  // Re-render charts if Chart.js is available
  try {
    renderDashboard();
    I18nManager.applyLanguageToDOM(document.body);
  } catch (err) {
    console.warn('Chart re-render skipped:', err);
  }

  if (state.currentLang === 'en') {
    showToast('Switched interface to English (LTR)', 'info');
  } else {
    showToast('تم تحويل الواجهة إلى العربية (RTL)', 'info');
  }

  if (typeof window.closeMobileSidebar === 'function' && window.innerWidth < 1024) {
    window.closeMobileSidebar();
  }
}
window.toggleLanguage = toggleLanguage;


