function togglePasswordVisibility() {
  const passInput = document.getElementById('login-password');
  const eyeIcon = document.getElementById('password-eye-icon');
  if (!passInput) return;
  if (passInput.type === 'password') {
    passInput.type = 'text';
    if (eyeIcon) {
      eyeIcon.classList.remove('fa-eye');
      eyeIcon.classList.add('fa-eye-slash');
    }
  } else {
    passInput.type = 'password';
    if (eyeIcon) {
      eyeIcon.classList.remove('fa-eye-slash');
      eyeIcon.classList.add('fa-eye');
    }
  }
}

async function handleLoginSubmit(event) {
  event.preventDefault();
  hideLoginAlert();

  const usernameInput = document.getElementById('login-username');
  const passwordInput = document.getElementById('login-password');
  const rememberCheckbox = document.getElementById('login-remember');
  const loginBtn = document.getElementById('login-btn');
  const btnText = document.getElementById('login-btn-text');
  const btnSpinner = document.getElementById('login-btn-spinner');

  const username = usernameInput ? usernameInput.value : '';
  const password = passwordInput ? passwordInput.value : '';
  const remember = rememberCheckbox ? rememberCheckbox.checked : false;

  // Set loading state
  if (loginBtn) loginBtn.disabled = true;
  if (btnText) btnText.textContent = 'جارٍ التوثيق عبر خادم الوزارة...';
  if (btnSpinner) btnSpinner.classList.remove('hidden');

  try {
    const authResult = await AuthServer.authenticate(username, password);

    if (authResult.status === '2fa_required') {
      // Transition to 2FA step
      currentPending2FAUserId = authResult.userId;
      document.getElementById('login-step-credentials').classList.add('hidden');
      document.getElementById('login-step-2fa').classList.remove('hidden');
      document.getElementById('login-otp').value = '123456'; // Default prefill for smooth evaluation
      start2FATimer();
      showLoginAlert(authResult.message, 'info');
      return;
    }

    // Success: save session and enter portal
    completeAuthentication(authResult, remember);

  } catch (error) {
    showLoginAlert(error.message || 'فشل التوثيق عبر الخادم. يرجى التحقق من بيانات الدخول.');
  } finally {
    if (loginBtn) loginBtn.disabled = false;
    if (btnText) btnText.textContent = 'تسجيل الدخول والتوثيق عبر الخادم';
    if (btnSpinner) btnSpinner.classList.add('hidden');
  }
}

let twoFaTimerInterval = null;
function start2FATimer() {
  let timeLeft = 45;
  const timerVal = document.getElementById('2fa-timer-val');
  if (twoFaTimerInterval) clearInterval(twoFaTimerInterval);
  twoFaTimerInterval = setInterval(() => {
    timeLeft--;
    if (timerVal) {
      const s = timeLeft < 10 ? '0' + timeLeft : timeLeft;
      timerVal.textContent = `00:${s}`;
    }
    if (timeLeft <= 0) {
      clearInterval(twoFaTimerInterval);
    }
  }, 1000);
}

function cancel2FA() {
  if (twoFaTimerInterval) clearInterval(twoFaTimerInterval);
  document.getElementById('login-step-2fa').classList.add('hidden');
  document.getElementById('login-step-credentials').classList.remove('hidden');
  currentPending2FAUserId = null;
  hideLoginAlert();
}

async function verify2FA() {
  const otp = document.getElementById('login-otp').value;
  const remember = document.getElementById('login-remember')?.checked;
  const verifyBtn = document.getElementById('verify-2fa-btn');

  if (verifyBtn) verifyBtn.disabled = true;
  try {
    const verifyEndpoint = '/api/v1/auth/verify-2fa';
    const res = await fetch(verifyEndpoint, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ otp, userId: currentPending2FAUserId })
    });
    const data = await res.json();
    if (!res.ok || data.status === 'error') {
      throw new Error(data.message || 'رمز التحقق غير صحيح');
    }
    completeAuthentication(data, remember);
  } catch (err) {
    showLoginAlert(err.message);
  } finally {
    if (verifyBtn) verifyBtn.disabled = false;
  }
}

function completeAuthentication(authResult, remember) {
  SessionManager.saveSession(authResult, remember);

  // Set active user
  const account = USERS_DATA.find(u => u.id === authResult.user.id) || authResult.user;
  switchUser(account.id);

  // Transition UI: Hide login screen, reveal app-root
  document.getElementById('login-screen').classList.add('hidden');
  document.getElementById('app-root').classList.remove('hidden');

  showToast(`مرحباً بك: ${account.name} (${account.roleName})`, 'success');
  logAudit('تسجيل دخول ناجح', `الحساب: ${account.name}`, `تم التوثيق عبر الخادم بنجاح - الجلسة: ${authResult.token.substring(0, 24)}...`);
}

async function handleLogout() {
  try {
    const logoutEndpoint = '/api/v1/auth/logout';
    await fetch(logoutEndpoint, { method: 'POST' });
  } catch (e) {
    // Ignore network error on logout
  }

  SessionManager.clearSession();
  state.currentUser = null;
  updateAuditViewVisibility(null);

  // UI transition
  document.getElementById('app-root').classList.add('hidden');
  document.getElementById('login-screen').classList.remove('hidden');

  // Reset form
  const passEl = document.getElementById('login-password');
  if (passEl) passEl.value = '';
  cancel2FA();
  hideLoginAlert();

  showToast('تم تسجيل الخروج بنجاح من النظام الآمن', 'info');
}

function showHelpModal() {
  document.getElementById('modal-login-help')?.classList.remove('hidden');
}

// ==========================================
// CHANGE PASSWORD & ADMIN RESET (6666) LOGIC
// ==========================================

function toggleInputPassword(inputId, iconId) {
  const inp = document.getElementById(inputId);
  const icon = document.getElementById(iconId);
  if (!inp) return;
  if (inp.type === 'password') {
    inp.type = 'text';
    if (icon) {
      icon.classList.remove('fa-eye');
      icon.classList.add('fa-eye-slash');
    }
  } else {
    inp.type = 'password';
    if (icon) {
      icon.classList.remove('fa-eye-slash');
      icon.classList.add('fa-eye');
    }
  }
}

function showChangePassAlert(msg, type = 'error') {
  const el = document.getElementById('cp-alert');
  if (!el) return;
  el.className = `mb-4 p-3 rounded-xl text-xs font-bold flex items-center gap-2 ${
    type === 'error'
      ? 'bg-rose-50 text-rose-700 border border-rose-200'
      : 'bg-emerald-50 text-emerald-700 border border-emerald-200'
  }`;
  el.innerHTML = `<i class="fa-solid ${type === 'error' ? 'fa-circle-exclamation' : 'fa-circle-check'}"></i><span>${msg}</span>`;
  el.classList.remove('hidden');
}

function openChangePasswordModal() {
  if (!state.currentUser) {
    showToast('يرجى تسجيل الدخول أولاً لتغيير كلمة المرور.', 'warning');
    return;
  }
  const modal = document.getElementById('modal-change-password');
  if (!modal) return;
  const sub = document.getElementById('cp-user-subtitle');
  if (sub) {
    sub.textContent = `الحساب النشط: ${state.currentUser.name} (${state.currentUser.username})`;
  }
  const form = document.getElementById('form-change-password');
  if (form) form.reset();
  const alertEl = document.getElementById('cp-alert');
  if (alertEl) alertEl.classList.add('hidden');
  modal.classList.remove('hidden');
}

function closeChangePasswordModal() {
  document.getElementById('modal-change-password')?.classList.add('hidden');
}

async function handleChangePasswordSubmit(event) {
  event.preventDefault();
  if (!state.currentUser) return;

  const currPass = document.getElementById('cp-current-password')?.value || '';
  const newPass = document.getElementById('cp-new-password')?.value || '';
  const confPass = document.getElementById('cp-confirm-password')?.value || '';

  if (!currPass.trim() || !newPass.trim() || !confPass.trim()) {
    showChangePassAlert('يرجى استيفاء جميع حقول كلمة المرور.');
    return;
  }
  if (newPass.trim().length < 4) {
    showChangePassAlert('يجب ألا تقل كلمة المرور الجديدة عن 4 أحرف أو أرقام.');
    return;
  }
  if (newPass.trim() !== confPass.trim()) {
    showChangePassAlert('كلمة المرور الجديدة وتأكيدها غير متطابقين.');
    return;
  }

  try {
    await AuthServer.changePassword(state.currentUser.id, currPass, newPass);
    logAudit('تغيير كلمة المرور', `الحساب: ${state.currentUser.name} (${state.currentUser.username})`, 'قام المستخدم بتغيير كلمة المرور الخاصة بحسابه بنجاح');
    closeChangePasswordModal();
    showToast('تم تغيير كلمة المرور الخاصة بحسابك وحفظها بنجاح.', 'success');
    if (state.currentView === 'audit' && canAccessAuditAndUsers()) {
      renderUsersTable();
    }
  } catch (err) {
    showChangePassAlert(err.message || 'تعذر تغيير كلمة المرور.');
  }
}

function openResetAccountsModal() {
  if (!canResetUserPasswords()) {
    showToast('عذراً: صلاحية عمل Reset للحسابات متاحة فقط لمدير عام الإدارة العامة للموهوبين والتعلم الذكي ومدير إدارة التعلم الذكي.', 'error');
    return;
  }
  const modal = document.getElementById('modal-reset-accounts');
  if (!modal) return;
  const searchInp = document.getElementById('modal-reset-search');
  if (searchInp) searchInp.value = '';
  renderResetAccountsModalList();
  modal.classList.remove('hidden');
}

function closeResetAccountsModal() {
  document.getElementById('modal-reset-accounts')?.classList.add('hidden');
}

function renderResetAccountsModalList() {
  const container = document.getElementById('modal-reset-accounts-list');
  if (!container) return;
  if (!canResetUserPasswords()) {
    container.innerHTML = '';
    return;
  }
  const q = (document.getElementById('modal-reset-search')?.value || '').trim().toLowerCase();
  const filtered = ACCOUNTS_DATABASE.filter(a => {
    if (!q) return true;
    return a.name.toLowerCase().includes(q) ||
           a.username.toLowerCase().includes(q) ||
           (a.gov && a.gov.toLowerCase().includes(q)) ||
           (a.roleName && a.roleName.toLowerCase().includes(q));
  });

  if (filtered.length === 0) {
    container.innerHTML = '<div class="p-6 text-center text-slate-400 text-xs">لا توجد حسابات مطابقة للبحث</div>';
    return;
  }

  container.innerHTML = filtered.map(a => {
    const isReset = a.password === '6666';
    const badge = isReset
      ? '<span class="bg-amber-100 text-amber-800 border border-amber-300 text-[10px] px-2 py-0.5 rounded-full font-bold">كلمة المرور الحالية: 6666</span>'
      : '<span class="bg-slate-100 text-slate-600 text-[10px] px-2 py-0.5 rounded-full font-semibold">كلمة مرور مخصصة</span>';

    return `
      <div class="py-2.5 px-3 hover:bg-slate-50 flex flex-col sm:flex-row sm:items-center justify-between gap-2 text-xs">
        <div>
          <div class="flex items-center gap-2 flex-wrap">
            <span class="font-bold text-slate-900">${a.name}</span>
            <span class="font-mono text-[11px] bg-slate-100 text-brand-700 px-1.5 py-0.5 rounded font-bold">${a.username}</span>
            ${a.gov ? `<span class="text-[10px] bg-cyan-50 text-cyan-800 border border-cyan-200 px-1.5 py-0.5 rounded font-bold">${a.gov}</span>` : ''}
            ${badge}
          </div>
          <div class="text-[11px] text-slate-500 mt-0.5">${a.roleName}</div>
        </div>
        <button type="button" onclick="handleAdminResetUserPassword('${a.id}')"
          class="shrink-0 px-3 py-1.5 bg-amber-600 hover:bg-amber-700 text-white font-bold rounded-xl text-xs transition shadow-sm flex items-center gap-1.5">
          <i class="fa-solid fa-rotate-left"></i>
          <span>عمل Reset إلى "6666"</span>
        </button>
      </div>
    `;
  }).join('');
}

async function handleAdminResetUserPassword(targetUserId) {
  if (!canResetUserPasswords()) {
    showToast('عذراً: هذه الصلاحية مكفولة فقط لمدير عام الإدارة العامة للموهوبين والتعلم الذكي ومدير إدارة التعلم الذكي.', 'error');
    return;
  }
  try {
    const res = await AuthServer.resetPassword(state.currentUser.id, targetUserId);
    const target = ACCOUNTS_DATABASE.find(a => a.id === targetUserId);
    const targetLabel = target ? `${target.name} (${target.username})` : targetUserId;
    logAudit(
      'إعادة ضبط كلمة المرور (Reset)',
      `الحساب: ${targetLabel}`,
      `قام ${state.currentUser.roleName} (${state.currentUser.name}) بعمل Reset للحساب وجعل كلمة المرور هي "6666"`
    );
    showToast(res.message || `تم عمل Reset للحساب وجعل كلمة المرور هي "6666" بنجاح.`, 'success');
    renderUsersTable();
    renderResetAccountsModalList();
  } catch (err) {
    showToast(err.message || 'تعذر إعادة تعيين كلمة المرور.', 'error');
  }
}




