  async function triggerCameraCapture(context = 'modal') {
    activePhotoTargetContext = context;
    document.getElementById('modal-photo-source-choice')?.classList.add('hidden');

    // On mobile / touch devices, trigger the native <input type="file" accept="image/*" capture="environment">
    // which opens the phone's native camera app directly and reliably.
    if (isMobileOrTouchDevice()) {
      const camInputId = context === 'portfolio' ? 'inp-portfolio-photo-camera' : 'inp-photo-camera';
      const camInput = document.getElementById(camInputId);
      if (camInput) {
        camInput.click();
        return;
      }
    }

    // If getUserMedia is supported (Desktop webcam or mobile browser supporting WebRTC), open live camera viewfinder
    if (navigator.mediaDevices && typeof navigator.mediaDevices.getUserMedia === 'function') {
      try {
        stopLiveCameraStream();
        activeCameraStream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: currentCameraFacingMode, width: { ideal: 720 }, height: { ideal: 720 } },
          audio: false
        });
        const videoEl = document.getElementById('live-camera-video');
        if (videoEl) {
          videoEl.srcObject = activeCameraStream;
          await videoEl.play().catch(() => {});
        }
        document.getElementById('modal-live-camera')?.classList.remove('hidden');
        return;
      } catch (err) {
        // Fallback to native file input with capture attribute if camera permission fails or is blocked in iframe
      }
    }

    const fallbackInputId = context === 'portfolio' ? 'inp-portfolio-photo-camera' : 'inp-photo-camera';
    document.getElementById(fallbackInputId)?.click();
  }

