    let h = videoEl.videoHeight;
    if (w > h) {
      if (w > maxDim) { h = Math.round((h * maxDim) / w); w = maxDim; }
    } else {
      if (h > maxDim) { w = Math.round((w * maxDim) / h); h = maxDim; }
    }
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(videoEl, 0, 0, w, h);
