  function updateStorageModalStatusBox() {
    if (!modalStorageStatusBox || typeof StorageManager === 'undefined') return;
    if (StorageManager.isServerConnected) {
      modalStorageStatusBox.className = 'p-4 rounded-2xl mb-4 border border-emerald-300 bg-emerald-50 text-emerald-950 flex items-start gap-3 shadow-sm';
      modalStorageStatusBox.innerHTML = `
        <div class="w-8 h-8 rounded-xl bg-emerald-600 text-white flex items-center justify-center text-sm shrink-0">
          <i class="fa-solid fa-circle-check"></i>
        </div>
        <div class="flex-1 text-xs">
          <div class="font-black text-sm text-emerald-900 mb-0.5">الخادم المحلي متصل بنجاح - الحفظ التلقائي مفعّل</div>
          <div class="text-emerald-800 leading-relaxed font-medium">
            يتم حفظ كافة تعديلات الطلاب، بيانات المراكز، وسجل التدقيق مباشرة داخل ملفات المجلد (<code class="bg-emerald-200/60 px-1 py-0.5 rounded font-mono">data/portal_database.json</code> و <code class="bg-emerald-200/60 px-1 py-0.5 rounded font-mono">data/saved_data.js</code>). عند نسخ المجلد لأي جهاز آخر، ستنتقل كافة البيانات والتعديلات معك تلقائياً.
          </div>
        </div>
      `;
    } else if (StorageManager.dirHandle) {
      modalStorageStatusBox.className = 'p-4 rounded-2xl mb-4 border border-blue-300 bg-blue-50 text-blue-950 flex items-start gap-3 shadow-sm';
      modalStorageStatusBox.innerHTML = `
        <div class="w-8 h-8 rounded-xl bg-blue-600 text-white flex items-center justify-center text-sm shrink-0">
          <i class="fa-solid fa-folder-check"></i>
        </div>
        <div class="flex-1 text-xs">
          <div class="font-black text-sm text-blue-900 mb-0.5">مجلد الموقع مربوط بالمتصفح مباشرة</div>
          <div class="text-blue-800 leading-relaxed font-medium">
            تم منح المتصفح صلاحية الحفظ المباشر داخل مجلد <code class="bg-blue-200/60 px-1 py-0.5 rounded font-mono">data</code>. أي تعديل يتم كتابته فوراً في ملفات المجلد لنقلها بأمان.
          </div>
        </div>
      `;
    } else if (StorageManager.hasUnsavedFolderChanges) {
      modalStorageStatusBox.className = 'p-4 rounded-2xl mb-4 border border-amber-300 bg-amber-50 text-amber-950 flex items-start gap-3 shadow-sm';
      modalStorageStatusBox.innerHTML = `
        <div class="w-8 h-8 rounded-xl bg-amber-600 text-white flex items-center justify-center text-sm shrink-0">
          <i class="fa-solid fa-triangle-exclamation"></i>
        </div>
        <div class="flex-1 text-xs">
          <div class="font-black text-sm text-amber-900 mb-0.5">تنبيه: توجد تعديلات جديدة محفوظة بالمتصفح فقط ولم تُحفظ في المجلد بعد</div>
          <div class="text-amber-800 leading-relaxed font-medium">
            أنت تستعرض الموقع مباشرة (<code class="bg-amber-200/60 px-1 py-0.5 rounded font-mono">file://</code>). لضمان نقل التعديلات الجديدة مع المجلد لجهاز آخر، يرجى الضغط على زر <b>«تنزيل ملف (saved_data.js)»</b> ووضعه داخل مجلد <code>data</code>، أو تشغيل البوابة عبر <b>(تشغيل_البوابة.bat)</b>.
          </div>
        </div>
      `;
    } else {
      modalStorageStatusBox.className = 'p-4 rounded-2xl mb-4 border border-slate-200 bg-slate-50 text-slate-800 flex items-start gap-3 shadow-sm';
      modalStorageStatusBox.innerHTML = `
        <div class="w-8 h-8 rounded-xl bg-slate-600 text-white flex items-center justify-center text-sm shrink-0">
          <i class="fa-solid fa-circle-check"></i>
        </div>
        <div class="flex-1 text-xs">
          <div class="font-black text-sm text-slate-900 mb-0.5">البيانات متطابقة مع ملفات المجلد</div>
          <div class="text-slate-600 leading-relaxed font-medium">
            البيانات المعروضة متطابقة حالياً مع ملف المجلد (<code class="bg-slate-200/60 px-1 py-0.5 rounded font-mono">data/saved_data.js</code>).
          </div>
        </div>
      `;
    }
  }

